package com.foundgine.benchmarks.highassurance;

import com.foundgine.core.semantic.authorization.SemanticAuthorizationException;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.UUID;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class TransferFundsParityTest {
    private static final UUID ACTOR = UUID.fromString("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa");
    private static final int TENANT = 42;
    private static UUID id(int n) { return UUID.fromString("00000000-0000-0000-0000-0000000000" + String.format("%012d", n)); }
    private static TransferFunds.BankAccount account(int n, String balance, String daily, boolean frozen) {
        return new TransferFunds.BankAccount(id(n), TENANT, ACTOR, new BigDecimal(balance), BigDecimal.ZERO, BigDecimal.ZERO, BigDecimal.ZERO, new BigDecimal(daily), frozen);
    }
    private static TransferFunds.Store store(TransferFunds.BankAccount... accounts) { var s=new TransferFunds.Store(); for(var a:accounts)s.add(a); return s; }
    private static TransferFunds.Command command(int s,int d,String amount,String key){return new TransferFunds.Command(id(s),id(d),new BigDecimal(amount),key);}

    @Test void transferEnforcesBusinessSemanticsAndAudit() { var src=account(100,"1000","5000",false); var dst=account(101,"250","5000",false); var audit=new TransferFunds.InMemoryAuditSink(); var service=new TransferFunds(store(src,dst),new TransferFunds.OwnershipAuthorization(),audit); var r=service.execute(ACTOR,TENANT,command(100,101,"400","k-1")); assertFalse(r.replay()); assertEquals(0,new BigDecimal("600").compareTo(serviceStore(service).get(id(100)).balance())); assertEquals(0,new BigDecimal("650").compareTo(serviceStore(service).get(id(101)).balance())); assertEquals(1,audit.entries().size()); assertEquals("succeeded",r.status()); assertTrue(r.effects().contains("transferFunds.debit")); }
    private static TransferFunds.Store serviceStore(TransferFunds service) { try { var f=TransferFunds.class.getDeclaredField("store"); f.setAccessible(true); return (TransferFunds.Store)f.get(service);} catch(Exception e){throw new AssertionError(e);} }
    @Test void availableFundsIncludesPendingAndHold(){var src=new TransferFunds.BankAccount(id(100),TENANT,ACTOR,new BigDecimal("1000"),new BigDecimal("300"),new BigDecimal("250"),BigDecimal.ZERO,new BigDecimal("5000"),false);var dst=account(101,"0","5000",false);var s=store(src,dst);var service=new TransferFunds(s,new TransferFunds.OwnershipAuthorization(),new TransferFunds.InMemoryAuditSink());assertThrows(IllegalStateException.class,()->service.execute(ACTOR,TENANT,command(100,101,"451","k-2")));}
    @Test void frozenDestinationDoesNotChangeBalances(){var src=account(100,"1000","5000",false);var dst=account(101,"250","5000",true);var s=store(src,dst);var service=new TransferFunds(s,new TransferFunds.OwnershipAuthorization(),new TransferFunds.InMemoryAuditSink());assertThrows(IllegalStateException.class,()->service.execute(ACTOR,TENANT,command(100,101,"100","k-3")));assertEquals(0,new BigDecimal("1000").compareTo(s.get(id(100)).balance()));assertEquals(0,new BigDecimal("250").compareTo(s.get(id(101)).balance()));}
    @Test void dailyLimitIsEnforced(){var src=new TransferFunds.BankAccount(id(100),TENANT,ACTOR,new BigDecimal("1000"),BigDecimal.ZERO,BigDecimal.ZERO,new BigDecimal("450"),new BigDecimal("500"),false);var dst=account(101,"0","5000",false);var service=new TransferFunds(store(src,dst),new TransferFunds.OwnershipAuthorization(),new TransferFunds.InMemoryAuditSink());assertThrows(IllegalStateException.class,()->service.execute(ACTOR,TENANT,command(100,101,"51","k-4")));}
    @Test void crossTenantIsRejected(){var src=account(100,"1000","5000",false);var dst=new TransferFunds.BankAccount(id(101),99,ACTOR,new BigDecimal("250"),BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,new BigDecimal("5000"),false);var s=store(src,dst);var service=new TransferFunds(s,new TransferFunds.OwnershipAuthorization(),new TransferFunds.InMemoryAuditSink());assertThrows(IllegalStateException.class,()->service.execute(ACTOR,TENANT,command(100,101,"100","k-5")));assertEquals(0,new BigDecimal("1000").compareTo(s.get(id(100)).balance()));}
    @Test void authorizationRecheckedAtExecution(){var auth=new TransferFunds.Authorization(){boolean allowed=false;public boolean canTransfer(UUID a,TransferFunds.BankAccount s,TransferFunds.BankAccount d){return allowed;}};var src=account(100,"1000","5000",false);var dst=account(101,"250","5000",false);var s=store(src,dst);var service=new TransferFunds(s,auth,new TransferFunds.InMemoryAuditSink());assertThrows(SemanticAuthorizationException.class,()->service.execute(ACTOR,TENANT,command(100,101,"100","k-6")));assertEquals(0,new BigDecimal("1000").compareTo(s.get(id(100)).balance()));}
    @Test void replayDoesNotDoubleDebit(){var src=account(100,"1000","5000",false);var dst=account(101,"0","5000",false);var audit=new TransferFunds.InMemoryAuditSink();var s=store(src,dst);var service=new TransferFunds(s,new TransferFunds.OwnershipAuthorization(),audit);var c=command(100,101,"400","replay-key");var a=service.execute(ACTOR,TENANT,c);var b=service.execute(ACTOR,TENANT,c);assertFalse(a.replay());assertTrue(b.replay());assertEquals(a.transferId(),b.transferId());assertEquals(0,new BigDecimal("600").compareTo(s.get(id(100)).balance()));assertEquals(1,audit.entries().size());}
    @Test void reusedKeyWithDifferentAmountRejected(){var service=new TransferFunds(store(account(100,"1000","5000",false),account(101,"0","5000",false)),new TransferFunds.OwnershipAuthorization(),new TransferFunds.InMemoryAuditSink());service.execute(ACTOR,TENANT,command(100,101,"100","bound-key"));assertThrows(IllegalStateException.class,()->service.execute(ACTOR,TENANT,command(100,101,"101","bound-key")));}
    @Test void concurrentSameKeyAppliedOnce() throws Exception {var audit=new TransferFunds.InMemoryAuditSink();var s=store(account(100,"1000","5000",false),account(101,"0","5000",false));var service=new TransferFunds(s,new TransferFunds.OwnershipAuthorization(),audit);var c=command(100,101,"400","concurrent-key");var pool=Executors.newFixedThreadPool(3);try{var fs=new Future<?>[3];for(int i=0;i<3;i++)fs[i]=pool.submit(()->service.execute(ACTOR,TENANT,c));for(var f:fs)f.get();assertEquals(0,new BigDecimal("600").compareTo(s.get(id(100)).balance()));assertEquals(0,new BigDecimal("400").compareTo(s.get(id(101)).balance()));assertEquals(1,audit.entries().size());}finally{pool.shutdownNow();}}
}
